<script setup lang="ts">
import type { Evaluation } from '../lib/api'
import { percent, downloadJSON } from '../lib/documents'
import { date } from '../lib/state'
import Icon from './Icon.vue'
defineProps<{evaluation:Evaluation}>()
const labels={baseline:'Baseline · 结构校验',grounded:'Grounded · 引文验证与修复'}
const statuses={queued:'排队中',running:'运行中',completed:'已完成',failed:'失败',cancelled:'已取消'}
</script>
<template><section class="comparison-report surface"><div class="section-head"><div><span class="topic-label">已保存的对比快照</span><h2>{{evaluation.documentTitle}}</h2></div><button class="button" @click="downloadJSON(evaluation,`comparison-${evaluation.id}.json`)"><Icon name="download"/>导出 JSON</button></div><p class="muted small">{{date(evaluation.createdAt)}} · 物理页 {{evaluation.pages.join('、')}} · 每策略 {{evaluation.count}} 题 · {{evaluation.model}}</p><p class="hash-line">资料 SHA256 {{evaluation.sourceHash}}</p><p class="comparison-scroll-hint small muted">左右滑动查看两个策略</p><div class="report-table-wrap"><table class="report-table"><thead><tr><th>策略 / 指标</th><th v-for="run in evaluation.runs" :key="run.jobId">{{labels[run.strategy]}}</th></tr></thead><tbody><tr><th>完成状态（失败仍计入）</th><td v-for="run in evaluation.runs" :key="run.jobId">{{statuses[run.status]}}<p v-if="run.error" class="error">{{run.error}}</p></td></tr><tr><th>任务成功率</th><td v-for="run in evaluation.runs" :key="run.jobId">{{run.status==='completed'?'1 / 1':'0 / 1'}}</td></tr><tr><th>实际题数 / 请求题数</th><td v-for="run in evaluation.runs" :key="run.jobId">{{run.questionCount}} / {{evaluation.count}}</td></tr><tr><th>规则通过率</th><td v-for="run in evaluation.runs" :key="run.jobId">{{percent(run.passRate)}}</td></tr><tr><th>引用覆盖率</th><td v-for="run in evaluation.runs" :key="run.jobId">{{percent(run.citationCoverage)}}</td></tr><tr><th>耗时</th><td v-for="run in evaluation.runs" :key="run.jobId">{{run.elapsedMs===null?'耗时未知（计时中断）':(run.elapsedMs/1000).toFixed(2)+' 秒'}}</td></tr><tr><th>模型调用次数</th><td v-for="run in evaluation.runs" :key="run.jobId">{{run.modelCalls}}</td></tr></tbody></table></div><ul class="report-limits"><li v-for="limit in evaluation.limitations" :key="limit">{{limit}}</li><li v-if="!evaluation.limitations.length">这是同一份资料上的两次真实任务快照，不代表模型总体正确率或学习效果；不估算费用。</li></ul></section></template>
